"""Ports the application depends on; adapters implement them."""

from typing import Protocol

from support_agent.application.audit import AuditEntry
from support_agent.application.model_protocol import ModelRequest, ModelResponse
from support_agent.domain.ids import CustomerId, IdempotencyKey, OrderId, TraceId
from support_agent.domain.orders import Order
from support_agent.domain.refunds import RefundRecord


class CustomerOrders(Protocol):
    """Orders of exactly one customer; foreign and missing orders both come back as None."""

    def list_orders(self) -> tuple[Order, ...]: ...

    def find_order(self, order_id: OrderId) -> Order | None: ...


class CustomerRefunds(Protocol):
    """Refund records of exactly one customer."""

    def for_order(self, order_id: OrderId) -> tuple[RefundRecord, ...]: ...

    def all(self) -> tuple[RefundRecord, ...]: ...

    def find_by_key(self, key: IdempotencyKey) -> RefundRecord | None: ...

    def add(self, record: RefundRecord) -> None: ...


class CustomerDataFactory(Protocol):
    """Builds repositories scoped to the authenticated customer; never to an ID chosen by the model."""

    def orders_for(self, customer_id: CustomerId) -> CustomerOrders: ...

    def refunds_for(self, customer_id: CustomerId) -> CustomerRefunds: ...


class ModelClient(Protocol):
    """One model completion: messages and tool schemas in, text and/or tool calls out."""

    def complete(self, request: ModelRequest) -> ModelResponse: ...


class AuditLog(Protocol):
    """Append-only audit trail keyed by trace_id."""

    def append(self, entry: AuditEntry) -> None: ...

    def entries(self, trace_id: TraceId) -> tuple[AuditEntry, ...]: ...
EOF
cat > adapters/mock_env_data.py <<'EOF'
"""Customer-scoped repositories over the mock commerce environment."""

from typing import Any

from mock_env import MockCommerceEnv
from support_agent.domain.ids import CustomerId, IdempotencyKey, ItemId, OrderId, RefundId, TraceId
from support_agent.domain.money import Currency, Money
from support_agent.domain.orders import Order, OrderLine, OrderStatus, Shipping
from support_agent.domain.refunds import RefundReason, RefundRecord, RefundState

REFUNDS_COLLECTION = "refunds"
KNOWN_STATUSES = {status.value for status in OrderStatus}


def _order_from_seed(raw: dict[str, Any]) -> Order:
    currency = Currency(raw["currency"])
    lines = tuple(
        OrderLine(ItemId(item["item_id"]), item["name"], int(item["quantity"]), Money.parse(item["unit_price"], currency))
        for item in raw["items"]
    )
    shipping = raw.get("shipping")
    status = raw["status"] if raw["status"] in KNOWN_STATUSES else OrderStatus.UNKNOWN
    return Order(
        order_id=OrderId(raw["order_id"]),
        customer_id=CustomerId(raw["customer_id"]),
        status=OrderStatus(status),
        total=Money.parse(raw["total"], currency),
        lines=lines,
        shipping=Shipping(shipping["carrier"], shipping["tracking_number"]) if shipping else None,
    )


def _refund_to_record(refund: RefundRecord) -> dict[str, Any]:
    return {
        "refund_id": refund.refund_id,
        "idempotency_key": refund.idempotency_key,
        "customer_id": refund.customer_id,
        "order_id": refund.order_id,
        "item_id": refund.item_id,
        "quantity": refund.quantity,
        "amount": str(refund.amount.amount),
        "currency": refund.amount.currency.value,
        "reason": refund.reason.value,
        "state": refund.state.value,
        "trace_id": refund.trace_id,
    }


def _refund_from_record(raw: dict[str, Any]) -> RefundRecord:
    return RefundRecord(
        refund_id=RefundId(raw["refund_id"]),
        idempotency_key=IdempotencyKey(raw["idempotency_key"]),
        customer_id=CustomerId(raw["customer_id"]),
        order_id=OrderId(raw["order_id"]),
        item_id=ItemId(raw["item_id"]),
        quantity=int(raw["quantity"]),
        amount=Money.parse(raw["amount"], Currency(raw["currency"])),
        reason=RefundReason(raw["reason"]),
        state=RefundState(raw["state"]),
        trace_id=TraceId(raw["trace_id"]),
    )


class MockEnvCustomerOrders:
    def __init__(self, env: MockCommerceEnv, customer_id: CustomerId) -> None:
        self._env = env
        self._customer_id = customer_id

    def list_orders(self) -> tuple[Order, ...]:
        return tuple(_order_from_seed(raw) for raw in self._env.orders() if raw["customer_id"] == self._customer_id)

    def find_order(self, order_id: OrderId) -> Order | None:
        return next((order for order in self.list_orders() if order.order_id == order_id), None)


class MockEnvCustomerRefunds:
    def __init__(self, env: MockCommerceEnv, customer_id: CustomerId) -> None:
        self._env = env
        self._customer_id = customer_id

    def all(self) -> tuple[RefundRecord, ...]:
        records = self._env.records(REFUNDS_COLLECTION)
        return tuple(_refund_from_record(raw) for raw in records if raw["customer_id"] == self._customer_id)

    def for_order(self, order_id: OrderId) -> tuple[RefundRecord, ...]:
        return tuple(record for record in self.all() if record.order_id == order_id)

    def find_by_key(self, key: IdempotencyKey) -> RefundRecord | None:
        return next((record for record in self.all() if record.idempotency_key == key), None)

    def add(self, record: RefundRecord) -> None:
        if record.customer_id != self._customer_id:
            raise ValueError("refund record does not belong to this customer scope")
        self._env.append_record(REFUNDS_COLLECTION, _refund_to_record(record))


class MockEnvDataFactory:
    def __init__(self, env: MockCommerceEnv) -> None:
        self._env = env

    def orders_for(self, customer_id: CustomerId) -> MockEnvCustomerOrders:
        return MockEnvCustomerOrders(self._env, customer_id)

    def refunds_for(self, customer_id: CustomerId) -> MockEnvCustomerRefunds:
        return MockEnvCustomerRefunds(self._env, customer_id)
EOF
cat > adapters/audit_log.py <<'EOF'
from support_agent.application.audit import AuditEntry, mask_email
from support_agent.domain.ids import TraceId


class InMemoryAuditLog:
    """Append-only; payload values are email-masked on write and entries come back as an immutable tuple."""

    def __init__(self) -> None:
        self._entries: list[AuditEntry] = []

    def append(self, entry: AuditEntry) -> None:
        masked = {key: mask_email(value) for key, value in entry.payload.items()}
        self._entries.append(AuditEntry(entry.trace_id, entry.kind, masked))

    def entries(self, trace_id: TraceId) -> tuple[AuditEntry, ...]:
        return tuple(entry for entry in self._entries if entry.trace_id == trace_id)

    def all_entries(self) -> tuple[AuditEntry, ...]:
        return tuple(self._entries)
EOF
cat > adapters/scripted_model.py <<'EOF'
from collections.abc import Sequence

from support_agent.application.model_protocol import ModelRequest, ModelResponse


class ScriptedModel:
    """Fake ModelClient that replays a fixed script; an exception in the script is raised (provider failure)."""

    def __init__(self, script: Sequence[ModelResponse | Exception]) -> None:
        self._script = list(script)
        self.requests: list[ModelRequest] = []

    def complete(self, request: ModelRequest) -> ModelResponse:
        self.requests.append(request)
        step = self._script.pop(0) if self._script else ModelResponse(text=None)
        if isinstance(step, Exception):
            raise step
        return step
EOF

