"""Executes a confirmed refund proposal after re-checking policy on fresh state."""

import logging
import threading
from collections.abc import Callable

from support_agent.application.ports import CustomerOrders, CustomerRefunds
from support_agent.domain.decisions import Decision, DecisionKind, ReasonCode
from support_agent.domain.ids import CustomerId, RefundId, TraceId
from support_agent.domain.refunds import RefundRecord, RefundState
from support_agent.domain.turn import ActionOutcome, ProposedRefund
from support_agent.policy.engine import PolicyEngine
from support_agent.policy.rules import RefundCheck

logger = logging.getLogger(__name__)

REFUND_ID_PREFIX = "RF-"


def _outcome(record: RefundRecord) -> ActionOutcome:
    return ActionOutcome(
        refund_id=record.refund_id,
        order_id=record.order_id,
        item_id=record.item_id,
        quantity=record.quantity,
        amount=record.amount,
        state=record.state,
    )


class RefundExecutor:
    def __init__(self, engine: PolicyEngine, new_id: Callable[[], str]) -> None:
        self._engine = engine
        self._new_id = new_id
        self._lock = threading.Lock()

    def execute(
        self,
        proposal: ProposedRefund,
        customer_id: CustomerId,
        orders: CustomerOrders,
        refunds: CustomerRefunds,
        trace_id: TraceId,
    ) -> ActionOutcome | Decision:
        with self._lock:
            existing = refunds.find_by_key(proposal.idempotency_key)
            if existing is not None:
                return _outcome(existing)
            if not self._still_valid(proposal, orders, refunds):
                return Decision(DecisionKind.DENY, ReasonCode.CONFIRMATION_STALE)
            record = self._issue(proposal, customer_id, trace_id)
            refunds.add(record)
        logger.info("refund issued refund_id=%s trace_id=%s", record.refund_id, trace_id)
        return _outcome(record)

    def _still_valid(self, proposal: ProposedRefund, orders: CustomerOrders, refunds: CustomerRefunds) -> bool:
        check = RefundCheck(
            order=orders.find_order(proposal.order_id),
            item_id=proposal.item_id,
            quantity=proposal.quantity,
            claimed_amounts=(),
            order_refunds=refunds.for_order(proposal.order_id),
            customer_refunds=refunds.all(),
        )
        decision = self._engine.assess_refund(check).decision
        return decision.kind is DecisionKind.NEEDS_CONFIRMATION and decision.amount == proposal.amount

    def _issue(self, proposal: ProposedRefund, customer_id: CustomerId, trace_id: TraceId) -> RefundRecord:
        return RefundRecord(
            refund_id=RefundId(f"{REFUND_ID_PREFIX}{self._new_id()}"),
            idempotency_key=proposal.idempotency_key,
            customer_id=customer_id,
            order_id=proposal.order_id,
            item_id=proposal.item_id,
            quantity=proposal.quantity,
            amount=proposal.amount,
            reason=proposal.reason,
            state=RefundState.ISSUED,
            trace_id=trace_id,
        )
"""Refund policy rules in table order (design section 4). Each returns None when it passes."""

from collections.abc import Callable
from dataclasses import dataclass

from support_agent.domain.decisions import Decision, DecisionKind, ReasonCode
from support_agent.domain.ids import ItemId
from support_agent.domain.money import Money
from support_agent.domain.orders import Order, OrderLine
from support_agent.domain.refunds import RefundRecord
from support_agent.policy.config import PolicyConfig
from support_agent.policy.refund_amounts import refund_amount, refundable_quantity, refunded_total

MIN_QUANTITY = 1


@dataclass(frozen=True)
class RefundCheck:
    order: Order | None
    item_id: ItemId
    quantity: int
    claimed_amounts: tuple[Money, ...]
    order_refunds: tuple[RefundRecord, ...]
    customer_refunds: tuple[RefundRecord, ...]


Rule = Callable[[RefundCheck, PolicyConfig], Decision | None]


def _deny(reason: ReasonCode) -> Decision:
    return Decision(DecisionKind.DENY, reason)


def resolve_line(check: RefundCheck) -> tuple[Order, OrderLine] | None:
    if check.order is None:
        return None
    line = check.order.line(check.item_id)
    return None if line is None else (check.order, line)


def order_in_scope(check: RefundCheck, _config: PolicyConfig) -> Decision | None:
    return _deny(ReasonCode.ORDER_NOT_FOUND) if check.order is None else None


def order_status_eligible(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    if check.order is not None and check.order.status not in config.refundable_statuses:
        return _deny(ReasonCode.ORDER_NOT_ELIGIBLE)
    return None


def item_on_order(check: RefundCheck, _config: PolicyConfig) -> Decision | None:
    if check.order is not None and check.order.line(check.item_id) is None:
        return _deny(ReasonCode.ITEM_NOT_ON_ORDER)
    return None


def something_left_to_refund(check: RefundCheck, _config: PolicyConfig) -> Decision | None:
    resolved = resolve_line(check)
    if resolved is not None and refundable_quantity(resolved[1], check.order_refunds) == 0:
        return _deny(ReasonCode.ALREADY_REFUNDED)
    return None


def quantity_within_refundable(check: RefundCheck, _config: PolicyConfig) -> Decision | None:
    resolved = resolve_line(check)
    if resolved is None:
        return None
    if check.quantity < MIN_QUANTITY or check.quantity > refundable_quantity(resolved[1], check.order_refunds):
        return _deny(ReasonCode.QUANTITY_EXCEEDS_REFUNDABLE)
    return None


def order_cap(check: RefundCheck, _config: PolicyConfig) -> Decision | None:
    resolved = resolve_line(check)
    if resolved is None:
        return None
    order, line = resolved
    already = refunded_total(check.order_refunds, order.total.currency)
    if already + refund_amount(line, check.quantity) > order.total:
        return _deny(ReasonCode.EXCEEDS_AMOUNT_PAID)
    return None


def approval_threshold(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = resolve_line(check)
    if resolved is None:
        return None
    amount = refund_amount(resolved[1], check.quantity)
    if amount > config.approval_threshold:
        return Decision(DecisionKind.ESCALATE, ReasonCode.ABOVE_APPROVAL_THRESHOLD, amount)
    return None


def customer_cap(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = resolve_line(check)
    if resolved is None:
        return None
    amount = refund_amount(resolved[1], check.quantity)
    already = refunded_total(check.customer_refunds, amount.currency)
    if already + amount > config.customer_auto_refund_cap:
        return Decision(DecisionKind.ESCALATE, ReasonCode.CUSTOMER_LIMIT_EXCEEDED, amount)
    return None


RULES: tuple[Rule, ...] = (
    order_in_scope,
    order_status_eligible,
    item_on_order,
    something_left_to_refund,
    quantity_within_refundable,
    order_cap,
    approval_threshold,
    customer_cap,
)


def confirmation_required(check: RefundCheck) -> Decision:
    resolved = resolve_line(check)
    if resolved is None:
        return _deny(ReasonCode.ORDER_NOT_FOUND)
    amount = refund_amount(resolved[1], check.quantity)
    return Decision(DecisionKind.NEEDS_CONFIRMATION, ReasonCode.CONFIRMATION_REQUIRED, amount)


def amount_dispute(check: RefundCheck, computed: Money) -> Decision | None:
    if any(claimed > computed for claimed in check.claimed_amounts):
        return Decision(DecisionKind.ESCALATE, ReasonCode.AMOUNT_DISPUTE, computed)
    return None
"""Runs the refund rules in order; the first failing rule decides."""

from dataclasses import dataclass

from support_agent.domain.decisions import Decision, DecisionKind
from support_agent.policy.config import PolicyConfig
from support_agent.policy.rules import RULES, RefundCheck, amount_dispute, confirmation_required

COMPUTED_AMOUNT_KINDS = frozenset({DecisionKind.NEEDS_CONFIRMATION, DecisionKind.ESCALATE})


@dataclass(frozen=True)
class RefundAssessment:
    decision: Decision
    dispute: Decision | None


class PolicyEngine:
    def __init__(self, config: PolicyConfig) -> None:
        self._config = config

    @property
    def config(self) -> PolicyConfig:
        return self._config

    def assess_refund(self, check: RefundCheck) -> RefundAssessment:
        decision = self._decide(check)
        dispute = None
        if decision.kind in COMPUTED_AMOUNT_KINDS and decision.amount is not None:
            dispute = amount_dispute(check, decision.amount)
        return RefundAssessment(decision=decision, dispute=dispute)

    def _decide(self, check: RefundCheck) -> Decision:
        for rule in RULES:
            failure = rule(check, self._config)
            if failure is not None:
                return failure
        return confirmation_required(check)
