class AuditEntry:
    trace_id: TraceId
    kind: AuditKind
    payload: Mapping[str, str]
    prompt_version: str
    model_id: str


class AuditSink(Protocol):
    def append(self, entry: AuditEntry) -> None: ...


def mask_email(text: str) -> str:
    return EMAIL_PATTERN.sub(r"\1***@\2", text)


def serialise(value: object) -> str:
    """One JSON form for audit payloads and tool results sent to the model."""
    return json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)


def _text(value: object) -> str:
    return value.value if isinstance(value, Enum) else str(value)


class Auditor:
    """The only writer of audit entries; every value is stored as plain text with the same stamp."""

    def __init__(self, sink: AuditSink, prompt_version: str, model_id: str) -> None:
        self._sink = sink
        self._prompt_version = prompt_version
        self._model_id = model_id

    def record(self, trace_id: TraceId, kind: AuditKind, /, **payload: object) -> None:
        values = {key: _text(value) for key, value in payload.items()}
        self._sink.append(AuditEntry(trace_id, kind, values, self._prompt_version, self._model_id))

